use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-poseidon-parallel";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=BTreeMap::new();let mut changed=Vec::new();let mut removed=0;
 for(rel,h)in m["source_files_sha256"].as_object().unwrap(){let orig=Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel);assert_eq!(hash(&orig),h.as_str().unwrap());let p=r.join("candidate").join(rel);let actual=hash(&p);if actual!=h.as_str().unwrap(){changed.push(rel.clone());let new=fs::read_to_string(&p).unwrap();let recovered:String=new.split_inclusive('\n').filter(|line|{let drop=line.starts_with("#[cfg(all(zopro_resource_schedule,zopro_poseidon_across8,");if drop{removed+=1;}!drop}).collect();assert_eq!(recovered,fs::read_to_string(orig).unwrap());}pins.insert(p.display().to_string(),actual);}
 assert_eq!(changed,vec!["crates/zopro-core/src/lib.rs","crates/zopro-core/src/solver.rs","crates/zopro-core/src/solver/sparse_poseidon.rs","crates/zopro-core/src/solver/sparse_poseidon/tests.rs"]);assert_eq!(removed,6);
 for rel in ["candidate/crates/zopro-core/src/solver/sparse_poseidon/across8.rs","candidate/crates/zopro-core/src/solver/sparse_poseidon/component.rs","candidate/crates/zopro-core/src/solver/sparse_poseidon/tests/across_refs.rs","candidate/crates/zopro-core/src/solver/sparse_poseidon/tests/parallel_refs.rs","probe.rs","support/perf.rs","setup.rs","design.md"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(p));}
 for rel in ["crates/zopro-core/src/solver/sparse_poseidon/across8.rs","crates/zopro-core/src/solver/sparse_poseidon/tests/across_refs.rs"]{assert_eq!(hash(r.join("candidate").join(rel)),hash(Path::new("/tmp/zopro-poseidon-across8/candidate").join(rel)));}
 save(r.join("source-pins.json"),&json!(pins));save(r.join("source-audit.json"),&json!({"original_files":170,"unchanged_originals":166,"changed_originals":changed,"original_bytes_recovered_after_removing6_cfg_lines":true,"parent_across8_kernel_exact":true,"parent_across_refs_tests_exact":true,"production_scheduler_unchanged":true,"field_source_unchanged":true,"in_place_descriptor_sort":true,"new_per_task_execution_copy":false,"new_lookup_table_or_plan":false,"production_changed":false}));
 let text=serde_json::to_string(&read("/tmp/zopro-poseidon-across8/native-plan.json")).unwrap().replace("/tmp/zopro-poseidon-across8",R);let mut plan:Value=serde_json::from_str(&text).unwrap();for step in plan["steps"].as_array_mut().unwrap(){if step["name"]=="core"{let tests=step["required_tests"].as_array_mut().unwrap();for name in ["fixture_tasks_have_disjoint_writes_and_initialized_reads","parallel_modes_match_every_buffer_at_real_worker_counts","grouping_moves_descriptors_only_and_reduces_ragged_tails","parallel_untagged_and_other_widths_preserve_scalar_execution"]{tests.push(json!(format!("solver::sparse_poseidon::tests::parallel_refs::{name}")));}}}save(r.join("native-plan.json"),&plan);println!("Frozen chain-aware parallel component; unchanged8-lane math; native116expected");
}
